key.query:
query GetCategoryPostsCursor($slug: ID!, $first: Int!, $after: String) {
  category(id: $slug, idType: SLUG) {
    databaseId
    name
    slug
    description
    posts(
      first: $first
      after: $after
      where: {orderby: {field: DATE, order: DESC}}
    ) {
      pageInfo {
        hasNextPage
        endCursor
        __typename
      }
      nodes {
        databaseId
        slug
        title(format: RENDERED)
        excerpt(format: RENDERED)
        featuredImage {
          node {
            sourceUrl
            mediaDetails {
              sizes {
                name
                sourceUrl
                __typename
              }
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
